from __future__ import annotations

# Minimal valid Opus frame (SILK NB 20ms, comfort noise / silence).
# These are NOT real decoded audio — they serve as opaque fixture data
# so the client playback pipeline can be exercised end-to-end.
#
# Hex: fc ff fe  →  Opus TOC + SILK range-coded comfort noise
# Base64 of those 3 bytes is "/P/+"
MOCK_OPUS_SILENCE_B64: str = "/P/+"

# Longer silence for multi-chunk tests.
MOCK_OPUS_CHUNKS: list[str] = ["/P/+", "/P/+", "/P/+", "/P/+", "/P/+"]


# Minimal valid JPEG used by the video_gallery scenario (64x64 indigo).
MOCK_GALLERY_JPEG_B64: str = (
    ""
)
